                                                                               int m2=10;
                                                                               int s1=3;

                                                                  void setup(){
                                                                 pinMode(s1,INPUT);
                                                                        roservo.attach(m1);
                                                                       botservo.attach(m2);
                                                                                                             }

                                                                  void loop()  {
                                                                                 int readValue=digitalRead(s1);
                                                                    if(readValue==HIGH){
                                                                              roservo.write(0);
                                                                             delay(300);
                                                                             botservo.write(60);
                                                                              delay(20);
                                                                                                                } else{
                                                                              botservo.write(0);
                                                                             delay(300);
                                                                             roservo.write(30);
                                                                              delay(20);
                                                                                                                }
                                                                          delay(300);
                                                                                                             }
