      로봇 프로그램 작성 활동 예시                 빨래(수건) 개기 구현 예시

  #include <Servo.h>

  Servo servo1;
  Servo servo2;
  Servo servo3;

  const int buttonPin = 2;
  int buttonState = 0;

  void setup() {
    servo1.attach(9);
    servo2.attach(10);
    servo3.attach(11);

   pinMode(buttonPin, INPUT_PULLUP);
   }

  void loop() {
    buttonState = digitalRead(buttonPin);

     if (buttonState == LOW) {
      rotateServos();
      }
   }

  void rotateServos() {
    servo1.write(60);
    delay(2000);
    servo1.write(0);
    delay(2000);

    servo2.write(60);
    delay(3000);
    servo2.write(0);
    delay(2000);

    servo3.write(60);
    delay(3000);
    servo3.write(0);
    delay(2000);
   }
